from collections import deque
class Solution:
    def minMoney(self, n, edges, k):
        adj = [[] for _ in range(n)]
        ws = sorted(set(w for _, _, w in edges))
        for u, v, w in edges:
            adj[u].append((v, w))
            adj[v].append((u, w))
        def ok(limit):
            dist = [-1] * n
            dist[0] = 0
            q = deque([0])
            while q:
                u = q.popleft()
                if dist[u] == k:
                    continue
                for v, w in adj[u]:
                    if w <= limit and dist[v] == -1:
                        dist[v] = dist[u] + 1
                        q.append(v)
            return dist[n - 1] != -1
        lo, hi = 0, len(ws) - 1
        ans = -1
        while lo <= hi:
            mid = (lo + hi) // 2
            if ok(ws[mid]):
                ans = ws[mid]
                hi = mid - 1
            else:
                lo = mid + 1
        return ans

