class Solution {
public:
    long long minMoney(int n, vector<vector<int>>& edges, int k) {
        vector<vector<pair<int,int>>> adj(n);
        set<int> wset;
        for (auto& e : edges) {
            adj[e[0]].push_back({e[1], e[2]});
            adj[e[1]].push_back({e[0], e[2]});
            wset.insert(e[2]);
        }
        vector<int> ws(wset.begin(), wset.end());
        auto ok = [&](int limit) {
            vector<int> dist(n, -1);
            dist[0] = 0;
            queue<int> q;
            q.push(0);
            while (!q.empty()) {
                int u = q.front(); q.pop();
                if (dist[u] == k) continue;
                for (auto& [v, w] : adj[u])
                    if (w <= limit && dist[v] == -1) {
                        dist[v] = dist[u] + 1;
                        q.push(v);
                    }
            }
            return dist[n - 1] != -1;
        };
        int lo = 0, hi = ws.size() - 1, ans = -1;
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            if (ok(ws[mid])) { ans = ws[mid]; hi = mid - 1; }
            else lo = mid + 1;
        }
        return ans;
    }
};

