class Solution {
    public long minMoney(int n, int[][] edges, int k) {
        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        TreeSet<Integer> wset = new TreeSet<>();
        for (int[] e : edges) {
            adj.get(e[0]).add(new int[]{e[1], e[2]});
            adj.get(e[1]).add(new int[]{e[0], e[2]});
            wset.add(e[2]);
        }
        int[] ws = wset.stream().mapToInt(Integer::intValue).toArray();
        java.util.function.IntPredicate ok = limit -> {
            int[] dist = new int[n];
            Arrays.fill(dist, -1);
            dist[0] = 0;
            ArrayDeque<Integer> q = new ArrayDeque<>();
            q.add(0);
            while (!q.isEmpty()) {
                int u = q.poll();
                if (dist[u] == k) continue;
                for (int[] vw : adj.get(u)) {
                    int v = vw[0], w = vw[1];
                    if (w <= limit && dist[v] == -1) {
                        dist[v] = dist[u] + 1;
                        q.add(v);
                    }
                }
            }
            return dist[n - 1] != -1;
        };
        int lo = 0, hi = ws.length - 1, ans = -1;
        while (lo <= hi) {
            int mid = (lo + hi) >>> 1;
            if (ok.test(ws[mid])) { ans = ws[mid]; hi = mid - 1; }
            else lo = mid + 1;
        }
        return ans;
    }
}

