var minMoney = function(n, edges, k) {
    const adj = Array.from({length: n}, () => []);
    const wset = new Set();
    for (const [u, v, w] of edges) {
        adj[u].push([v, w]);
        adj[v].push([u, w]);
        wset.add(w);
    }
    const ws = [...wset].sort((a, b) => a - b);
    const ok = limit => {
        const dist = new Array(n).fill(-1);
        dist[0] = 0;
        const q = [0];
        for (let qi = 0; qi < q.length; qi++) {
            const u = q[qi];
            if (dist[u] === k) continue;
            for (const [v, w] of adj[u])
                if (w <= limit && dist[v] === -1) {
                    dist[v] = dist[u] + 1;
                    q.push(v);
                }
        }
        return dist[n - 1] !== -1;
    };
    let lo = 0, hi = ws.length - 1, ans = -1;
    while (lo <= hi) {
        const mid = (lo + hi) >> 1;
        if (ok(ws[mid])) { ans = ws[mid]; hi = mid - 1; }
        else lo = mid + 1;
    }
    return ans;
};
